import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/** Body of {@code POST /api/v1/links}. URL and alias rules are enforced by their validators. */
public record CreateLinkRequest(
    @Schema(example = "https://example.com/some/very/long/path") @NotBlank String url,
    @Schema(
            example = "promo-2026",
            description = "Optional. 4-32 chars of letters, digits, '_' or '-'.",
            nullable = true)
        String customAlias,
    @Schema(
            example = "spring campaign flyer",
            description = "Optional note for the owner, at most 280 characters.",
            nullable = true)
        @Size(max = 280)
        String note) {

  /** Without a note. */
  public CreateLinkRequest(String url, String customAlias) {
    this(url, customAlias, null);
  }
}
